<?php
require_once __DIR__.'/includes/auth.php'; require_login(); $uid=current_user_id();
$search=trim((string)($_GET['q']??'')); $sql="SELECT user_id,full_name,username,profile_color,profile_photo FROM users WHERE user_id<>? AND status='active'"; $params=[$uid];
if($search!==''){$sql.=" AND (full_name LIKE ? OR username LIKE ?)";$params[]='%'.$search.'%';$params[]='%'.$search.'%';}$sql.=' ORDER BY full_name LIMIT 40';$st=$pdo->prepare($sql);$st->execute($params);$users=$st->fetchAll();
$st=$pdo->prepare("SELECT c.conversation_id,c.conversation_type,c.title,c.updated_at,
 (SELECT m.message_text FROM messages m WHERE m.conversation_id=c.conversation_id ORDER BY m.message_id DESC LIMIT 1) AS message_text,
 (SELECT m.message_type FROM messages m WHERE m.conversation_id=c.conversation_id ORDER BY m.message_id DESC LIMIT 1) AS message_type,
 (SELECT m.sent_at FROM messages m WHERE m.conversation_id=c.conversation_id ORDER BY m.message_id DESC LIMIT 1) AS sent_at,
 (SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.conversation_id AND m.sender_id<>? AND m.message_id>cm.last_read_message_id AND m.deleted_at IS NULL) AS unread_count,
 (SELECT GROUP_CONCAT(u.full_name ORDER BY u.full_name SEPARATOR ', ') FROM conversation_members cm2 JOIN users u ON u.user_id=cm2.user_id WHERE cm2.conversation_id=c.conversation_id AND cm2.user_id<>?) AS people,
 (SELECT u.profile_color FROM conversation_members cm2 JOIN users u ON u.user_id=cm2.user_id WHERE cm2.conversation_id=c.conversation_id AND cm2.user_id<>? LIMIT 1) AS profile_color
 FROM conversation_members cm JOIN conversations c ON c.conversation_id=cm.conversation_id WHERE cm.user_id=? ORDER BY COALESCE((SELECT MAX(m.sent_at) FROM messages m WHERE m.conversation_id=c.conversation_id),c.updated_at) DESC");$st->execute([$uid,$uid,$uid,$uid]);$conversations=$st->fetchAll();
$st=$pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$st->execute([$uid]);$notificationCount=(int)$st->fetchColumn();
$pageTitle='Messages';require __DIR__.'/includes/header.php'; ?>
<section class="dashboard-heading"><div><div class="eyebrow">YOUR SPACE</div><h1>Messages<span class="heading-dot">.</span></h1><p class="muted">Private chats, groups and people—all in one place.</p></div><div class="dashboard-actions"><a class="button button-primary" href="create_group.php">＋ New group</a><a class="button button-ghost" href="notifications.php">Notifications <span class="count-pill"><?= $notificationCount ?></span></a><div class="user-chip"><span class="avatar avatar-small" style="--avatar-color:#7c3aed"><?= e(strtoupper(mb_substr($_SESSION['full_name'],0,1))) ?></span><div><strong><?= e($_SESSION['full_name']) ?></strong><small>@<?= e($_SESSION['username']??'you') ?></small></div></div></div></section>
<div class="dashboard-grid"><section class="panel conversations-panel"><div class="panel-heading"><h2>Recent chats</h2><span class="count-pill"><?= count($conversations) ?></span></div><?php if(!$conversations): ?><div class="empty-state"><div class="empty-icon">☏</div><h3>No conversations yet</h3><p>Find a person or create a group to start chatting.</p></div><?php else: ?><div class="conversation-list"><?php foreach($conversations as $c): $label=$c['conversation_type']==='group'?$c['title']:($c['people']?:'Private chat'); $preview=$c['message_text']?:($c['message_type']==='image'?'📷 Image':($c['message_type']==='file'?'📎 File':'Start the conversation')); ?><a class="conversation-row" href="chat.php?id=<?= (int)$c['conversation_id'] ?>"><span class="avatar" style="--avatar-color:<?= e($c['profile_color']?:'#7c3aed') ?>"><?= e(strtoupper(mb_substr($label,0,1))) ?></span><span class="conversation-copy"><strong><?= e($label) ?> <?= $c['conversation_type']==='group'?' <small class="tag">GROUP</small>':'' ?></strong><small><?= e(mb_strimwidth((string)$preview,0,48,'…')) ?></small></span><span class="conversation-meta"><small><?= $c['sent_at']?e(date('H:i',strtotime($c['sent_at']))):'' ?></small><?php if((int)$c['unread_count']>0): ?><b class="unread-badge"><?= (int)$c['unread_count'] ?></b><?php else: ?><span>›</span><?php endif; ?></span></a><?php endforeach; ?></div><?php endif; ?></section>
<section class="panel people-panel"><div class="panel-heading"><div><h2>Find people</h2><p class="muted small-text">Search by name or username.</p></div><span class="people-icon">⌕</span></div><form class="search-form" method="get"><input name="q" value="<?= e($search) ?>" placeholder="Search people..." aria-label="Search people"><button class="button button-primary" type="submit">Search</button></form><div class="people-list"><?php if(!$users): ?><div class="empty-mini">No users matched, or create another account to test.</div><?php endif; ?><?php foreach($users as $u): ?><div class="person-row"><span class="avatar avatar-small" style="--avatar-color:<?= e($u['profile_color']) ?>"><?php if($u['profile_photo']): ?><img class="avatar-photo" src="<?= e($u['profile_photo']) ?>" alt=""><?php else: ?><?= e(strtoupper(mb_substr($u['full_name'],0,1))) ?><?php endif; ?></span><span class="person-copy"><strong><?= e($u['full_name']) ?></strong><small>@<?= e($u['username']) ?></small></span><form method="post" action="start_chat.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['user_id'] ?>"><button class="icon-button" type="submit" title="Message <?= e($u['full_name']) ?>" aria-label="Message user">↗</button></form></div><?php endforeach; ?></div></section></div>
<?php require __DIR__.'/includes/footer.php'; ?>
